func providerActive(env, slot, adapter string) bool {
	switch env {
	case "development":
		if slot == "ggg/billing" && adapter == "ggg/system/billing-local" {
			return true
		}
		if slot == "ggg/identity" && adapter == "ggg/system/identity-dev" {
			return true
		}
		if slot == "ggg/mail" && adapter == "ggg/system/mail-dev" {
			return true
		}
		if slot == "ggg/storage" && adapter == "ggg/system/storage-filesystem" {
			return true
		}
	case "test":
		if slot == "ggg/billing" && adapter == "ggg/system/billing-local" {
			return true
		}
		if slot == "ggg/identity" && adapter == "ggg/system/identity-dev" {
			return true
		}
		if slot == "ggg/mail" && adapter == "ggg/system/mail-dev" {
			return true
		}
		if slot == "ggg/storage" && adapter == "ggg/system/storage-filesystem" {
			return true
		}
	case "production":
		if slot == "ggg/billing" && adapter == "ggg/system/billing-polar" {
			return true
		}
		if slot == "ggg/identity" && adapter == "ggg/system/identity-clerk" {
			return true
		}
		if slot == "ggg/mail" && adapter == "ggg/system/mail-resend" {
			return true
		}
		if slot == "ggg/storage" && adapter == "ggg/system/storage-s3" {
			return true
		}
	}
	return false
}

func (r *Runtime) Health(ctx context.Context) apphost.HealthReport {
	return r.healthCache.Get(ctx, r.health)
}

func (r *Runtime) Handler() http.Handler { return r.HTTPHandler }

func (r *Runtime) Run(ctx context.Context) error {
	for _, start := range r.start {
		if err := start(ctx); err != nil {
			return err
		}
	}
	return nil
}

func (r *Runtime) Close(ctx context.Context) error {
	var errs []error
	for i := len(r.stop) - 1; i >= 0; i-- {
		if err := r.stop[i](ctx); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}
